<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { io } from 'socket.io-client'
import { api, apiBaseURL } from 'boot/axios'
import AuthDialog from 'components/AuthDialog.vue'
import IAChatComponent from 'components/IAChatComponent.vue'
import ProductDemoImage from 'components/ProductDemoImage.vue'
import LandingVideoMonitor from 'components/landing3d/LandingVideoMonitor.vue'
import { botBuilderHeroVideo } from 'src/data/landingHeroVideo'
const router = useRouter(), route = useRoute(), $q = useQuasar()
const assistantOpen = ref(false)
const loginOpen = ref(false), confirming = ref(false), paymentMessage = ref(''), buying = ref(false), checkoutOpen = ref(false), order = ref(null), purchased = ref(false)
const offer = ref({ available: false, priceCents: null, originalPriceCents: null })
const checkoutReturn = computed(() => typeof route.query.order_nsu === 'string' && typeof route.query.transaction_nsu === 'string' && typeof (route.query.slug || route.query.invoice_slug) === 'string')
const authReturnPath = computed(() => checkoutReturn.value ? route.fullPath : '/whatsappbotbuilder?comprar=1')
const money = cents => cents == null ? 'Consulte disponibilidade' : (Number(cents) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_user_token') || ''}` } })
let socket, timer
function connect() {
  if (socket || !localStorage.getItem('aito_user_token')) return
  const url = new URL(apiBaseURL, window.location.origin)
  socket = io(`${url.origin}/products`, { auth: { token: localStorage.getItem('aito_user_token') }, transports: ['websocket', 'polling'], reconnectionDelay: 1500 })
  socket.on('purchase.updated', event => { if (!order.value || order.value.orderNsu === event.orderNsu) refreshPurchase() })
  socket.on('connect', () => { if (checkoutOpen.value) refreshPurchase() })
}
async function refreshPurchase() {
  if (!localStorage.getItem('aito_user_token')) return
  try { const data = (await api.get('/products/whatsappbotbuilder', headers())).data.data; purchased.value = data.licenses.some(item => item.active); if (order.value) order.value = data.orders.find(item => item.orderNsu === order.value.orderNsu) || order.value } catch { /* o próximo evento ou consulta reconcilia a confirmação */ }
}
async function buy() {
  if (buying.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; return }
  checkoutOpen.value = true; buying.value = true; paymentMessage.value = ''; connect()
  clearInterval(timer); timer = setInterval(() => { if (checkoutOpen.value) refreshPurchase() }, 15000)
  try {
    await refreshPurchase()
    if (!purchased.value) order.value = (await api.post('/products/whatsappbotbuilder/checkout', {}, headers())).data.data
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Não foi possível abrir o checkout. Tente novamente.' }
  finally { buying.value = false }
}
async function confirmCheckout() {
  if (!checkoutReturn.value || confirming.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; paymentMessage.value = 'Entre com a conta usada na compra para confirmar o pagamento.'; return }
  checkoutOpen.value = true; confirming.value = true; paymentMessage.value = ''; connect()
  try {
    await api.post('/products/whatsappbotbuilder/confirm', { order_nsu: route.query.order_nsu, transaction_nsu: route.query.transaction_nsu, slug: route.query.slug || route.query.invoice_slug }, headers())
    await refreshPurchase()
    $q.notify({ type: 'positive', message: 'Pagamento confirmado. Seu código e token estão em Meus produtos.' })
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Pagamento aguardando confirmação. Consulte novamente em instantes.' }
  finally { confirming.value = false }
}
function onAuthenticated() { connect(); if (checkoutReturn.value) confirmCheckout(); else buy() }
onMounted(async () => { try { offer.value = (await api.get('/products/whatsappbotbuilder/public')).data.data } catch { paymentMessage.value = 'Oferta indisponível no momento.' } connect(); if (checkoutReturn.value) confirmCheckout(); else if (route.query.comprar === '1') buy() })
onBeforeUnmount(() => { socket?.disconnect(); clearInterval(timer) })
</script>
